import{_ as i,o as s,c as t,a6 as a}from"./chunks/framework.BBdhcoHf.js";const g=JSON.parse('{"title":"ADR-013: Peer SDK Core Design Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/013-peer-sdk-design.md","filePath":"adr/013-peer-sdk-design.md","lastUpdated":1772916561000}'),n={name:"adr/013-peer-sdk-design.md"};function o(r,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[a(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/013-peer-sdk-design.md for this page in Markdown format</div><h1 id="adr-013-peer-sdk-core-design-decisions" tabindex="-1">ADR-013: Peer SDK Core Design Decisions <a class="header-anchor" href="#adr-013-peer-sdk-core-design-decisions" aria-label="Permalink to “ADR-013: Peer SDK Core Design Decisions”">​</a></h1><ul><li><strong>Date</strong>: 2026-02-24</li><li><strong>Status</strong>: Accepted</li><li><strong>Affects</strong>: SDK, Runtime, Transport</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>@sideband/peer</code> is the primary consumer-facing SDK wrapping the runtime and transport layers. Several design choices have cross-layer normative implications — they constrain implementation across <code>@sideband/secure-relay</code>, <code>@sideband/runtime</code>, and <code>@sideband/peer</code>. This ADR formalizes the two most architecturally significant decisions from the RFC development cycle.</p><h2 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to “Decisions”">​</a></h2><h3 id="_1-sbrp-negotiator-role-separation" tabindex="-1">1. SBRP Negotiator Role Separation <a class="header-anchor" href="#_1-sbrp-negotiator-role-separation" aria-label="Permalink to “1. SBRP Negotiator Role Separation”">​</a></h3><p><strong>Options:</strong></p><ul><li>A) Single <code>sbrpNegotiator(options: SbrpNegotiatorOptions)</code> with all options in one bag</li><li>B) Discriminated union: <code>sbrpNegotiator({ role: &quot;client&quot; | &quot;daemon&quot;, ...options })</code></li><li>C) Separate factories per role</li></ul><p><strong>Chosen:</strong> C (separate factories)</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/** Client-side SBRP (browser or CLI connecting to a daemon) */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> relayClientNegotiator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SbrpClientOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Negotiator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/** Daemon-side SBRP (service accepting relay connections) */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> relayDaemonNegotiator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SbrpDaemonOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Negotiator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><strong>Rationale:</strong> <code>SbrpNegotiatorOptions</code> mixes client-only fields (TOFU pinning, <code>onFirstConnection</code>, <code>trustPolicy</code>, <code>controlPlaneUrl</code>) with daemon-only fields (<code>serverIdentity</code>, <code>resumable</code>, <code>pauseBufferLimitBytes</code>). Options A and B allow invalid combinations to compile and fail only at runtime — violating the &quot;hard to misuse&quot; design goal. Separate factories give each role a dedicated, focused type with unambiguous autocomplete and error messages.</p><p><strong>Note:</strong> The single <code>sbrpNegotiator()</code> function was abandoned during design — it was never shipped. No migration/deprecation path is needed.</p><h3 id="_2-nats-style-event-pattern-syntax" tabindex="-1">2. NATS-Style Event Pattern Syntax <a class="header-anchor" href="#_2-nats-style-event-pattern-syntax" aria-label="Permalink to “2. NATS-Style Event Pattern Syntax”">​</a></h3><p><strong>Decision:</strong> Pub/sub event names and subscription patterns use NATS-style dot-separated syntax.</p><p><strong>Grammar:</strong></p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>event_name = segment (&quot;.&quot; segment)*</span></span>
<span class="line"><span>segment    = token | &quot;*&quot; | &quot;&gt;&quot;</span></span>
<span class="line"><span>token      = 1*SAFE_CHAR</span></span>
<span class="line"><span>SAFE_CHAR  = ALPHA | DIGIT | &quot;-&quot; | &quot;_&quot;</span></span></code></pre></div><p><strong>Wildcards</strong> (subscription patterns only; invalid in literal event names):</p><table tabindex="0"><thead><tr><th>Wildcard</th><th>Meaning</th></tr></thead><tbody><tr><td><code>*</code></td><td>Matches exactly one segment</td></tr><tr><td><code>&gt;</code></td><td>Matches one or more segments; MUST be the final segment</td></tr></tbody></table><p><strong>Constraints:</strong></p><ul><li>Max length: 255 bytes UTF-8</li><li>Case-sensitive: <code>User.Created</code> ≠ <code>user.created</code></li><li>No empty segments, no leading/trailing dots</li><li><code>**</code> is explicitly forbidden (this is not a glob syntax)</li><li><code>*</code> and <code>&gt;</code> must each occupy an entire segment</li></ul><p><strong>Normative rules:</strong></p><ol><li>Patterns are validated at <code>onPattern()</code> call time.</li><li>Invalid patterns throw <code>PeerError</code> with code <code>invalid_pattern</code>.</li><li><code>**</code> MUST be rejected with an error directing the user to <code>&gt;</code>.</li></ol><p><strong>Rationale:</strong> NATS semantics are proven in production messaging systems, have a simple non-regex matching implementation, and are familiar to pub/sub developers. Explicit prohibition of <code>**</code> prevents confusion with filesystem glob patterns.</p><h3 id="_3-server-only-export-split-sideband-peer-server" tabindex="-1">3. Server-only export split (<code>@sideband/peer/server</code>) <a class="header-anchor" href="#_3-server-only-export-split-sideband-peer-server" aria-label="Permalink to “3. Server-only export split (@sideband/peer/server)”">​</a></h3><p><code>listen()</code> and server-side types are exported from the <code>@sideband/peer/server</code> subpath, not from the package root.</p><p><strong>Rationale:</strong> <code>listen()</code> imports Node/Bun server APIs. Including it in the root bundle would pull these into browser builds. Isolating it under <code>/server</code> keeps the main entry point tree-shakeable and safe for browser consumers without requiring conditional imports or polyfills.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>@sideband/peer</code> exposes <code>relayClientNegotiator</code> and <code>relayDaemonNegotiator</code>. They live in peer (not secure-relay) because peer already depends on runtime for <code>Negotiator</code>/<code>SbpNegotiator</code>, while secure-relay stays a pure crypto library with zero runtime dependencies.</li><li><code>@sideband/peer</code> validates event patterns client-side via <code>onPattern()</code> / <code>validatePattern()</code>.</li><li>All documentation and examples MUST use <code>&gt;</code> (not <code>**</code>) for multi-segment wildcard patterns.</li><li>Server-side consumers import from <code>@sideband/peer/server</code>; browser consumers import from <code>@sideband/peer</code>.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><code>docs/sdk/peer.md</code> §6.4, §6.8 — Peer SDK RFC (SBRP negotiator and pub/sub API)</li><li>ADR-008: Channel Subject Validation</li><li>ADR-006: RPC Envelope</li><li>ADR-014: Peer SDK Session Signal Handling</li></ul>`,31)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
